/**
 * 负责流水线与 handler 共享的夜间状态及执行端口契约。
 * 输入为捕获的阶段操作、已付效果和 actor 查询；输出为有类型的贡献及原状态引用。
 * 机械、觉醒和原毒的内建生产者提交 sourced intent，源原体/因果信息只供运行时消费。
 * 旧注入 effect/claim 保留接受宽度；其额外 kind/origin/getter 不被当作新协议读取。
 * 所有内建原毒（含受赠及学者加成）均有来源；此契约不查询 World 或提交库存。
 * 外部自定义注入仍保留明确 legacy 接受政策，不把同名字段视为 owned 来源。
 */
import { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import {
  ActionProvider,
  ActionRequest,
  ActionRequestExtras,
  ActionStage,
  EntityId,
  GameEvent,
  ExileFeedback,
  NightSummary,
  Role,
} from "../../../../core/domain/model";
import { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { RoleCatalog } from "../../roles/catalog";
import type { DreamNightLink } from "../../roles/dreamer/night_frame";
import type { NightAbilityActorQuery } from "../../roles/night-ability-actors";
import type { AliveComponent } from "../../../../core/domain/components/alive";
import type { NativeNightFailurePolicy } from "../../../../rulesets/native-night-failure-policy";
import type { NativeNightTargetPolicy } from "../../../../rulesets/native-night-target-policy";
import type { NativeNightEffects } from "../../../../rulesets/native-night-effects";

import type {
  NightPoisonClaim,
  NightInspectionAttack,
  NightFoxInspectionClaim,
  NightMechanicalEffect,
  NightGuardClaim,
  NightMerchantBacklash,
  NightBlackMarketBacklash,
  NightAwakenedEffect,
  NightMechanicalIntent,
  NightAwakenedIntent,
  NightOriginalPoisonIntent,
} from "../../../../core/domain/night_effects";

/** 狼刀选定时捕获的原生命及印记引用；目标序号相同不代表原体和生命版本仍有效。 */
export interface WolfKnifeTargetScope {
  targetId: EntityId;
  life: AliveComponent;
  version: number;
  marks: StatusMarksComponent;
}

/**
 * 同一夜按阶段顺序累积的运行状态，流水线创建，具体 handler 写入所属效果。
 * 包含原组件、回执和当前性查询，不能直接序列化为玩家观察或录制格式。
 * 效果条目是运行提案或捕获记录；空容器存在不表示已付、有效或已标死，这些由各所有者分别核对。
 */
export interface NightStageState {
  /** 学者／导师在原冲突检查点产生的死亡与刀口；不是直接修改 Alive 的指令。 */
  modifierDeaths?: import("../../../../core/domain/night_effects").NightLifeScope[];
  modifierKnifeTargets?: EntityId[];
  /** 增益保留原领取回执和可选印记原体，伤害组合前仍须核对效果与目标的当前性。 */
  modifierBonusEffects?: Array<{
    kind: import("../../roles/scholar_mentor/night_frame").ModifierBonusKind;
    receipt: import("../../roles/scholar_mentor/night_frame").ModifierBonusReceipt;
    marks?: ReturnType<NightStageContext["ensureMarks"]>;
  }>;
  wolfChatOrder: EntityId[];
  endedWolves: Set<EntityId>;
  wolfVotes: Record<number, number>;
  wolfTarget: EntityId | null;
  wolfTargetScope?: WolfKnifeTargetScope;
  /** 实际参与选定普通狼刀的投票者；票表的目标键不能代替投票者名单。 */
  wolfTargetVoters?: EntityId[];
  seerChecks: NightSummary["seerChecks"];
  /** 已捕获的摄梦关系保留施法者和目标原生命；保护与死亡闭包由同一梦实例推导。 */
  dreamLinks: DreamNightLink[];
  /** 内建有来源 intent 与旧注入 claim 共存；仅同名字段不能把旧对象变成内建来源。 */
  poisonClaims?: Array<NightOriginalPoisonIntent | NightPoisonClaim>;
  inspectionAttacks?: NightInspectionAttack[];
  retaliationAttacks?: import("../../../../core/domain/night_effects").NightRetaliationAttack[];
  nightImmunities?: import("../../../../core/domain/night_effects").NightImmunityClaim[];
  /** 恶夜骑士开夜时的原体绑定供付款后反射使用；含状态和回调，不是可公开的角色知识。 */
  evilKnightBindings?: Map<
    EntityId,
    NonNullable<ReturnType<typeof import("../../roles/evil_knight/state").captureEvilKnight>>
  >;
  foxInspections?: NightFoxInspectionClaim[];
  guardClaims?: NightGuardClaim[];
  merchantBacklashes?: NightMerchantBacklash[];
  blackMarketBacklashes?: NightBlackMarketBacklash[];
  /** 机械效果按护盾、攻击、失败分别保留，消费次数和来源规则由具体能力控制。 */
  mechanicalEffects?: {
    shields: Array<NightMechanicalIntent<"mechanical-shield"> | NightMechanicalEffect>;
    attacks: Array<NightMechanicalIntent<"mechanical-attack"> | NightMechanicalEffect>;
    failures: Array<NightMechanicalIntent<"mechanical-failure"> | NightMechanicalEffect>;
  };
  /** 觉醒效果与机械效果分列，不能因形状相近而合并付款或退休政策。 */
  awakenedEffects?: {
    shields: Array<NightAwakenedIntent<"awakened-shield"> | NightAwakenedEffect>;
    attacks: Array<NightAwakenedIntent<"awakened-attack"> | NightAwakenedEffect>;
  };
}

/**
 * 阶段 handler 使用的运行端口：请求、候选查询和效果写入均在当前阶段执行。
 * 异步行动返回后仍需检查 isCurrent 及具体原体许可；持有此上下文不自动获得领域提交权限。
 */
export interface NightStageContext {
  isCurrent(): boolean;
  readonly previousExile: Readonly<ExileFeedback> | null;
  world: World;
  roleCatalog: RoleCatalog;
  readonly nightActors: NightAbilityActorQuery;
  readonly nativeNightFailure: NativeNightFailurePolicy;
  readonly nativeNightTargets: NativeNightTargetPolicy;
  readonly nativeNightEffects: NativeNightEffects;
  toolGateway: ToolGateway;
  events: GameEvent[];
  actionProvider: ActionProvider;
  currentDay(): number;
  makeRequest(
    actorId: EntityId,
    allowedTools: ActionRequest["allowedTools"],
    context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
  ): ActionRequest;
  getAliveByRole(role: Role): EntityId[];
  ensureMarks(entityId: EntityId): StatusMarksComponent;
  pickMajorityTarget(votes: Record<number, number>): EntityId | null;
  /** 迷雾有限板在所有投票者明确放弃后使用的回退，随机流具名且可复现。 */
  pickMistKnife?(ids: readonly EntityId[]): EntityId | null;
  shuffleWolves(ids: EntityId[]): EntityId[];
  state: NightStageState;
}

/** 默认收集器按原 priority 装配，流水线按计划原顺序执行；处理器返回不等于效果已造成实际死亡。 */
export interface NightStageHandler {
  id: string;
  priority: number;
  execute(ctx: NightStageContext): Promise<void>;
}

/**
 * 负责学者／导师本夜选择及独立加成阶段。
 * 输入为有资格的加成行动者、原目标 receipt 和已校验行动；输出保留已付效果及本职历史。
 * 加成毒在原 receipt.commit 与印记付款之后附带来源，独立于女巫或受赠瓶数。
 * 本模块不重新计算别族的已付目标，也不将原体句柄或因果 Symbol 写入事件。
 */
import { COMPONENT, Camp, Phase, StatusMark, type RoleComponent } from "../../../../core";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { originalPoisonIntent, type NightLifeScope } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import {
  beginScholarMentorNight,
  commitScholarMentorChoice,
  settleScholarMentorChoices,
  scholarMentorStateForRole,
  scholarMentorChoiceTargets,
  assertScholarMentorRosterCurrent,
  scholarMentorBonusActors,
  scholarMentorBonusTargets,
  captureScholarMentorBonus,
  scholarMentorConflictDeaths,
  type ModifierBonusKind,
} from "./night_frame";
const choose: NightStageHandler = {
  id: "scholar_mentor_choice",
  priority: 50,
  async execute(ctx) {
    const day = ctx.currentDay(),
      pending = beginScholarMentorNight(ctx.world, day);
    for (const actorId of ctx.world.entityIds()) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role),
        state = scholarMentorStateForRole(role);
      if (!state) continue;
      if (!pending.includes(actorId)) {
        const reason =
          day === 1
            ? "first_night"
            : ctx.world.getAliveEntityIds().includes(actorId)
              ? "exhausted"
              : "dead";
        ctx.events.push({
          timestamp: Date.now(),
          type: "modifier_choice_skipped",
          payload: { actorId, day, reason },
          audience: Object.freeze([actorId]),
        });
        continue;
      }
      const modes = (["enhance", "weaken"] as const).filter((mode) => state.remaining[mode] === 1);
      const request = ctx.makeRequest(actorId, ["modify_skill"], {
        stage: "scholar_mentor_choice",
        requiresAction: true,
        action_failure_policy: "error",
        allow_fallback: false,
        modifier_modes: modes,
        modifier_candidates: scholarMentorChoiceTargets(ctx.world, day, actorId),
      });
      assertScholarMentorRosterCurrent(ctx.world);
      const action = await ctx.actionProvider.getAction(request);
      assertScholarMentorRosterCurrent(ctx.world);
      if (!ctx.isCurrent() || ctx.currentDay() !== day)
        throw new Error("scholar_mentor_choice_stale");
      if (action?.name !== "modify_skill") throw new Error("scholar_mentor_choice_missing");
      const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
        phase: Phase.Night,
        day,
      });
      assertScholarMentorRosterCurrent(ctx.world);
      if (!ctx.isCurrent() || !result.ok || result.sanitizedCall?.name !== "modify_skill")
        throw new Error("scholar_mentor_choice_invalid");
      const { mode, target_id } = result.sanitizedCall.args;
      commitScholarMentorChoice(ctx.world, day, actorId, mode, target_id);
      ctx.events.push({
        timestamp: Date.now(),
        type: "modifier_choice_committed",
        payload: { actorId, day, mode, targetId: target_id },
        audience: Object.freeze([actorId]),
      });
    }
    const result = settleScholarMentorChoices(ctx.world, day);
    ctx.state.modifierDeaths = scholarMentorConflictDeaths(ctx.world, day);
    if (result.conflict !== null)
      ctx.events.push({
        timestamp: Date.now(),
        type: "modifier_conflict_resolved",
        payload: { day, kind: result.conflict, targetId: result.pendingDeaths[0]! },
        audience: Object.freeze([]),
      });
  },
};
export function assertScholarMentorBonusEffects(ctx: NightStageContext): void {
  assertScholarMentorRosterCurrent(ctx.world);
  for (const effect of ctx.state.modifierBonusEffects ?? []) {
    const target = effect.receipt.target;
    if (
      !effect.receipt.effectCurrent() ||
      (target &&
        (ctx.world.getComponent(target.id, COMPONENT.Alive) !== target.life ||
          aliveLifeVersion(target.life) !== target.version)) ||
      (effect.marks &&
        target &&
        ctx.world.getComponent(target.id, COMPONENT.StatusMarks) !== effect.marks)
    )
      throw new Error("scholar_mentor_bonus_effect_stale");
  }
}
function bonus(kind: ModifierBonusKind, priority: number): NightStageHandler {
  return {
    id: "scholar_mentor_bonus_" + kind,
    priority,
    async execute(ctx) {
      const day = ctx.currentDay();
      for (const actorId of scholarMentorBonusActors(ctx.world, day, kind)) {
        const request = ctx.makeRequest(actorId, ["bonus_action"], {
          stage: "scholar_mentor_bonus",
          requiresAction: true,
          action_failure_policy: "error",
          allow_fallback: false,
          modifier_bonus_kind: kind,
          modifier_bonus_candidates: scholarMentorBonusTargets(ctx.world, day, actorId, kind),
        });
        assertScholarMentorRosterCurrent(ctx.world);
        const action = await ctx.actionProvider.getAction(request);
        assertScholarMentorRosterCurrent(ctx.world);
        if (!ctx.isCurrent() || ctx.currentDay() !== day)
          throw new Error("scholar_mentor_bonus_stale");
        if (action?.name !== "bonus_action" || action.args.kind !== kind)
          throw new Error("scholar_mentor_bonus_missing");
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        assertScholarMentorRosterCurrent(ctx.world);
        if (
          !ctx.isCurrent() ||
          !result.ok ||
          result.sanitizedCall?.name !== "bonus_action" ||
          result.sanitizedCall.args.kind !== kind
        )
          throw new Error("scholar_mentor_bonus_invalid");
        const { target_id: targetId, abstain } = result.sanitizedCall.args;
        const receipt = captureScholarMentorBonus(ctx.world, day, actorId, kind, targetId);
        const inspection =
          kind === "check" && targetId !== null
            ? resolveInspection(ctx.world, targetId, "camp", ctx.roleCatalog)
            : null;
        if (kind === "check" && targetId !== null && !inspection)
          throw new Error("scholar_mentor_inspection_invalid");
        if (!receipt.isCurrent() || !ctx.isCurrent()) throw new Error("scholar_mentor_bonus_stale");
        receipt.commit();
        if (targetId !== null && receipt.target) {
          if (kind === "check") {
            ctx.state.seerChecks.push({
              seerId: actorId,
              targetId,
              isWerewolf: inspection!.camp === Camp.Wolf,
              result: { ...inspection! },
            });
            (ctx.state.modifierBonusEffects ??= []).push({ kind, receipt });
          } else {
            const marks = ctx.ensureMarks(targetId);
            if (kind === "guard") {
              marks.add(StatusMark.GuardMark);
              (ctx.state.guardClaims ??= []).push({
                target: receipt.target,
                marks,
                isCurrent: receipt.effectCurrent,
              });
            } else if (kind === "poison") {
              marks.add(StatusMark.PoisonMark);
              // source 在原对象字段求值位置读取一次；receipt 的付款和当前性仍归 frame。
              let effectSource: NightLifeScope;
              (ctx.state.poisonClaims ??= []).push(originalPoisonIntent({
                source: (effectSource = receipt.source),
                target: receipt.target,
                isCurrent: receipt.effectCurrent,
              }, {
                family: "scholar-mentor",
                day,
                stage: "scholar_mentor_bonus",
                actorLife: effectSource,
                requestedTargetId: targetId,
                abilityId: "bonus:poison",
              }));
            } else {
              marks.add(StatusMark.WolfKillMark);
              (ctx.state.modifierKnifeTargets ??= []).push(targetId);
            }
            (ctx.state.modifierBonusEffects ??= []).push({ kind, receipt, marks });
          }
        }
        ctx.events.push({
          timestamp: Date.now(),
          type: "modifier_bonus_resolved",
          payload: {
            actorId,
            day,
            kind,
            targetId,
            abstain,
            ...(inspection ? { isWerewolf: inspection.camp === Camp.Wolf } : {}),
          },
          audience: Object.freeze([actorId]),
        });
      }
      assertScholarMentorBonusEffects(ctx);
    },
  };
}
export const SCHOLAR_MENTOR_NIGHT_STAGES: NightStageHandler[] = [
  choose,
  bonus("guard", 350),
  bonus("kill", 450),
  bonus("poison", 550),
  bonus("check", 650),
];
